import{_ as a,C as i,o,c as n,E as c,a2 as l}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"安全的命令名，不等于执行权限","description":"","frontmatter":{"title":"安全的命令名，不等于执行权限","date":"2026-08-20","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"When the visible action name does not fully determine what will execute, what evidence should a digital employee use before treating an action as authorized?","summary":"命令标签记录的是意图，不是配置与可执行上下文可能产生的全部行为。同日 Codex 变更说明：当语法无法确定实际动作时，执行准入应 Fail-closed，并交由显式策略裁决。","sources":["research/analysis/Q-20260820-01-effective-execution-authority.md"],"item_id":"Q-20260820-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-20-command-name-execution-authority-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-20-command-name-execution-authority.md","filePath":"zh/digital-employee/2026-08-20-command-name-execution-authority.md","lastUpdated":1787382334000}'),r={name:"zh/digital-employee/2026-08-20-command-name-execution-authority.md"};function s(d,e,u,p,m,h){const t=i("ArticleCover");return o(),n("div",null,[c(t,{image:"/assets/covers/daily-2026-08-20-command-name-execution-authority-cover-v2.png",kicker:"数字员工 · 每日研究",title:"安全的命令名，不等于执行权限",summary:"命令标签记录的是意图，不是配置与可执行上下文可能产生的全部行为。同日 Codex 变更说明：当语法无法确定实际动作时，执行准入应 Fail-closed，并交由显式策略裁决。",version:"Q-20260820-01",status:"Daily Runtime V5 · 2026-08-20",languageHref:"/en/digital-employee/2026-08-20-command-name-execution-authority",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="安全的命令名-不等于执行权限" tabindex="-1">安全的命令名，不等于执行权限 <a class="header-anchor" href="#安全的命令名-不等于执行权限" aria-label="Permalink to &quot;安全的命令名，不等于执行权限&quot;">​</a></h1><p><code>git status</code> 看起来只是读取仓库状态。但在可配置的仓库里，眼前这几个词并不能完整描述进程可能执行的内容：Git 配置可以把名义上的只读操作重定向到 Helper。数字员工如果只识别命令名，就可能把一个熟悉标签误当成充分授权。</p><p>2026 年 8 月 20 日合并的一项 Codex 变更正面处理了这个边界。Git 被移出 Unix 与 Windows 的 Known-safe Command Shortcut。在 <code>UnlessTrusted</code> 审批策略下，普通 <code>git status</code> 会进入 <code>NeedsApproval</code>，除非显式 Execution-policy Rule 已授权。针对 Absolute Executable Path 的测试还区分了由策略覆盖的 Host Executable 与另一条未匹配的 Git Path。端到端回归实际触发真人审批，并把拒绝结果保留为命令结果。</p><p>这些证据支持的并不是“Git 都不安全”，而是一条更准确的规则：<strong>名义 Action Name 是 Intent Evidence，不是 Execution Authority；Effective Execution Identity、Governing Policy 与后续 Effect Containment 必须分别记录。</strong></p><h2 id="标签描述意图-上下文决定行为" tabindex="-1">标签描述意图，上下文决定行为 <a class="header-anchor" href="#标签描述意图-上下文决定行为" aria-label="Permalink to &quot;标签描述意图，上下文决定行为&quot;">​</a></h2><p>命令 Allowlist 很有吸引力，因为它便宜、确定。如果 <code>status</code> 这样的 Token 永远映射到一个固定实现，Lexical Classifier 确实可以减少不必要的审批。但当 Executable、Repository Configuration、Wrapper 或 Environment 能改变同一段文本的实际行为时，这个前提就失效了。</p><p>这对数字员工尤其重要，因为 Visible Action 往往同时是 Agent 与 Reviewer 看到的主要证据。请求可能写着“检查仓库状态”，Effective Execution Path 却会读取能够启动其他程序的配置。名义命令仍然表达了有价值的 Intent，但已经无法建立完整 Operation Identity。</p><p>Absolute-path 测试把区别变得很具体：覆盖某个已声明 Host Executable 的 Policy Rule，不会自动授权另一条未匹配 Git Path。因此，命令拼写只是 Policy Identity 的一个组成部分；Executable Identity 与 Execution Context 同样重要。</p><h2 id="fail-closed-不等于凡事都询问" tabindex="-1">Fail-closed 不等于凡事都询问 <a class="header-anchor" href="#fail-closed-不等于凡事都询问" aria-label="Permalink to &quot;Fail-closed 不等于凡事都询问&quot;">​</a></h2><p>取消 Known-safe Shortcut，并不意味着 Classifier 变成最终 Authority。回归行为仍保留不同 Policy Semantics：<code>UnlessTrusted</code> 在没有显式规则时请求批准，而 <code>OnRequest</code> 保持自己的策略逻辑。变更只是把无法确定的情况从“自动安全”退回 Governing Policy。</p><p>这是关键的架构分账。Classification 回答“我们掌握了哪些关于这次动作的证据”；Policy 回答“在当前 Authority 下是否允许执行”。不断扩大的硬编码 Allowlist 会把两者混为一谈，并在本地配置改变实际行为后迅速过期。</p><p>Always-ask 也不是唯一替代方案。它可能制造 Approval Fatigue，却没有改善 Reviewer 获得的证据。更合理的契约是：在行为受到独立约束时，允许低成本 Classifier 优化；只要语法无法证明安全，就必须回到显式 Policy。</p><h2 id="把授权记录绑定到实际执行" tabindex="-1">把授权记录绑定到实际执行 <a class="header-anchor" href="#把授权记录绑定到实际执行" aria-label="Permalink to &quot;把授权记录绑定到实际执行&quot;">​</a></h2><p>一份可用的 Execution Record 至少应分开保存四个事实：</p><ul><li>用户或 Agent 表达的 Nominal Intent；</li><li>可能改变行为的 Effective Executable 与 Context；</li><li>授予或拒绝 Authority 的可归责、可版本化 Policy Decision；</li><li>执行后关于 External Effect 是否被约束和对账的证据。</li></ul><p>第一项帮助人理解动作，第二项确保决策针对真正会运行的 Operation，第三项标识 Authority Channel，第四项阻止系统把一次成功准入夸大成“结果必然安全”。</p><p>这种分离也改变了 Approval Interface 应展示的内容。当 Executable Path、Repository Configuration 或 Helper Risk 会实质改变执行时，只重复同一条命令文本是不够的。充分知情的批准需要看到改变策略结果的证据，而不是多一个确认按钮。</p><h2 id="approval-仍然不是-effect-containment" tabindex="-1">Approval 仍然不是 Effect Containment <a class="header-anchor" href="#approval-仍然不是-effect-containment" aria-label="Permalink to &quot;Approval 仍然不是 Effect Containment&quot;">​</a></h2><p>已合并代码与测试是来自单一实现的公开一手证据，不是跨 Agent Runtime 的独立安全评估。它没有枚举所有 Git Helper Path，也没有建立 Binary Provenance、Repository-configuration Integrity 或 Sandbox Behavior。</p><p>更重要的是，Approval 只授权一次有界 Execution Decision。它不会证明 Helper 按预期行为，不会证明所有 External Effect 都被 Sandbox 约束，也不会证明远端状态已经完成 Reconciliation。这些属于后续 Gate，需要各自的证据。</p><p>真正需要回答的问题不再是某条命令能否永久进入“安全清单”，而是一次 Authority Decision 最少需要哪些 Effective-execution Evidence。Policy Identity 能否纳入 Executable 与相关 Configuration Digest，而不让每次动作的成本过高？Repository State 改变后，哪些旧规则必须失效？数字员工的安全来自这些转换可以被明确记录和测试，而不是让熟悉的名字代替实际 Operation。</p><p><strong>一手证据：</strong> <a href="https://github.com/openai/codex/commit/3b45c29062ff0e76e71c91b6753290400e7fa8da" target="_blank" rel="noreferrer">OpenAI Codex 合并提交 3b45c290</a>。公开代码与仓库测试支持本文描述的有界实现行为，但不构成对完整执行安全的独立验证。</p>',22))])}const x=a(r,[["render",s]]);export{y as __pageData,x as default};
